compile.workshop:
variables {
    global:
        0: A
        1: B
    player:
        0: B
        2: C
}

rule ("receiver") {
    event {
        Ongoing - Each Player;
        All;
        All;
    }
    actions {
        Set Global Variable(A, (Global.B).C);
    }
}

